1	/**
2	 * CompanyFinancial — Dashboard financeiro da empresa (Slice 3, R12-R16).
3	 *
4	 * Seções:
5	 *  1. Teto de gasto: configurar limite mensal + barra de progresso colorida.
6	 *  2. Faturamento: CTA se não informado; exibe valor quando declarado.
7	 *  3. BI: ratio custo/hora + custo-%-faturamento; gasto por freela; custo de no-show; flags de concentração.
8	 *  4. Seletor de período: mês atual / mês anterior.
9	 *
10	 * Padrões: useState + useEffect, imports relativos, TS strict, design neo-brutalista empresa.
11	 */
12	
13	import { useState } from 'react';
14	import {
15	  TrendingDown,
16	  AlertTriangle,
17	  BarChart2,
18	  Users,
19	  Clock,
20	  DollarSign,
21	  ChevronDown,
22	  ChevronUp,
23	  Info,
24	} from 'lucide-react';
25	import { useSpendLimit, useFinancialBI } from '../../hooks/useFinancialBI';
26	import { customPeriod, currentMonthPeriod } from '../../services/financialBIService';
27	import type { BIPeriod } from '../../services/financialBIService';
28	import { useToast } from '../../contexts/ToastContext';
29	
30	// ---------------------------------------------------------------------------
31	// Helpers de formatacao
32	// ---------------------------------------------------------------------------
33	
34	function formatBRL(value: number): string {
35	  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
36	}
37	
38	function formatHours(h: number): string {
39	  if (h === 0) return '0h';
40	  return `${h.toFixed(1)}h`;
41	}
42	
43	function formatPercent(v: number): string {
44	  return `${v.toFixed(1)}%`;
45	}
46	
47	// Retorna o periodo do mes anterior
48	function previousMonthPeriod(): BIPeriod {
49	  const now = new Date();
50	  const firstOfThisMonth = new Date(now.getFullYear(), now.getMonth(), 1);
51	  const firstOfPrev = new Date(now.getFullYear(), now.getMonth() - 1, 1);
52	  const y = firstOfPrev.getFullYear();
53	  const m = String(firstOfPrev.getMonth() + 1).padStart(2, '0');
54	  const fy = firstOfThisMonth.getFullYear();
55	  const fm = String(firstOfThisMonth.getMonth() + 1).padStart(2, '0');
56	  return customPeriod(`${y}-${m}-01`, `${fy}-${fm}-01`);
57	}
58	
59	function periodLabel(p: BIPeriod): string {
60	  const d = new Date(p.start + 'T12:00:00');
61	  return d.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
62	}
63	
64	// ---------------------------------------------------------------------------
65	// Subcomponente: SpendLimitCard
66	// ---------------------------------------------------------------------------
67	
68	interface SpendLimitCardProps {
69	  spendLimitAmount: number | null;
70	  accumulatedSpend: number;
71	  loading: boolean;
72	  onSave: (amount: number, thresholds: number[]) => Promise<boolean>;
73	}
74	
75	function SpendLimitCard({ spendLimitAmount, accumulatedSpend, loading, onSave }: SpendLimitCardProps) {
76	  const [editing, setEditing] = useState(false);
77	  const [inputValue, setInputValue] = useState('');
78	  const [saving, setSaving] = useState(false);
79	  const { addToast } = useToast();
80	
81	  const pct = spendLimitAmount && spendLimitAmount > 0
82	    ? Math.min((accumulatedSpend / spendLimitAmount) * 100, 100)
83	    : 0;
84	
85	  const barColor =
86	    pct >= 100
87	      ? 'bg-red-600'
88	      : pct >= 90
89	        ? 'bg-red-400'
90	        : pct >= 80
91	          ? 'bg-yellow-400'
92	          : 'bg-primary';
93	
94	  const textColor =
95	    pct >= 100
96	      ? 'text-red-600'
97	      : pct >= 90
98	        ? 'text-red-500'
99	        : pct >= 80
100	          ? 'text-yellow-600'
101	          : 'text-primary';
102	
103	  async function handleSave() {
104	    const parsed = parseFloat(inputValue.replace(',', '.'));
105	    if (isNaN(parsed) || parsed <= 0) {
106	      addToast('Informe um valor valido maior que zero.', 'error');
107	      return;
108	    }
109	    setSaving(true);
110	    const ok = await onSave(parsed, [80, 90, 100]);
111	    setSaving(false);
112	    if (ok) {
113	      addToast('Teto de gasto salvo!', 'success');
114	      setEditing(false);
115	      setInputValue('');
116	    } else {
117	      addToast('Erro ao salvar o teto. Tente novamente.', 'error');
118	    }
119	  }
120	
121	  if (loading) {
122	    return (
123	      <div className="bg-white border-2 border-black rounded-2xl p-6 animate-pulse space-y-4">
124	        <div className="h-6 bg-gray-200 rounded-xl w-1/3" />
125	        <div className="h-4 bg-gray-200 rounded-xl w-2/3" />
126	        <div className="h-4 bg-gray-200 rounded-xl w-full" />
127	      </div>
128	    );
129	  }
130	
131	  return (
132	    <div className="bg-white border-2 border-black rounded-2xl p-6 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
133	      <div className="flex items-center justify-between mb-4">
134	        <div className="flex items-center gap-2">
135	          <DollarSign size={20} strokeWidth={3} />
136	          <h2 className="text-xl font-black uppercase">Teto de Gasto Mensal</h2>
137	        </div>
138	        <button
139	          onClick={() => {
140	            setEditing((e) => !e);
141	            setInputValue(spendLimitAmount ? String(spendLimitAmount) : '');
142	          }}
143	          className="text-sm font-black uppercase px-4 py-2 rounded-xl border-2 border-black hover:bg-black hover:text-white transition-colors"
144	          aria-label={editing ? 'Cancelar edicao do teto' : 'Editar teto de gasto'}
145	        >
146	          {editing ? 'Cancelar' : spendLimitAmount ? 'Editar' : 'Configurar'}
147	        </button>
148	      </div>
149	
150	      {editing ? (
151	        <div className="space-y-3">
152	          <label htmlFor="spendLimitInput" className="block text-sm font-black uppercase text-gray-600">
153	            Novo teto mensal (R$)
154	          </label>
155	          <input
156	            id="spendLimitInput"
157	            type="number"
158	            min="1"
159	            step="0.01"
160	            value={inputValue}
161	            onChange={(e) => setInputValue(e.target.value)}
162	            placeholder="Ex: 5000,00"
163	            className="w-full border-2 border-black rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-primary text-lg font-bold tabular-nums"
164	          />
165	          <p className="text-xs text-gray-500 flex items-center gap-1">
166	            <Info size={12} />
167	            Alertas in-app ao atingir 80%, 90% e 100% do teto. WhatsApp em breve.
168	          </p>
169	          <button
170	            onClick={handleSave}
171	            disabled={saving || !inputValue}
172	            className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
173	          >
174	            {saving ? 'Salvando...' : 'Salvar Teto'}
175	          </button>
176	        </div>
177	      ) : spendLimitAmount && spendLimitAmount > 0 ? (
178	        <div className="space-y-3">
179	          <div className="flex items-end justify-between">
180	            <div>
181	              <p className="text-xs font-bold uppercase text-gray-500">Gasto acumulado</p>
182	              <p className={`text-2xl font-black tabular-nums ${textColor}`}>{formatBRL(accumulatedSpend)}</p>
183	            </div>
184	            <div className="text-right">
185	              <p className="text-xs font-bold uppercase text-gray-500">Teto</p>
186	              <p className="text-2xl font-black tabular-nums">{formatBRL(spendLimitAmount)}</p>
187	            </div>
188	          </div>
189	          {/* Barra de progresso */}
190	          <div className="w-full bg-gray-100 border-2 border-black rounded-full h-5 overflow-hidden">
191	            <div
192	              className={`h-full rounded-full transition-all ${barColor}`}
193	              style={{ width: `${pct}%` }}
194	              role="progressbar"
195	              aria-valuenow={Math.round(pct)}
196	              aria-valuemin={0}
197	              aria-valuemax={100}
198	              aria-label={`Progresso do teto de gasto: ${Math.round(pct)}%`}
199	            />
200	          </div>
201	          <p className={`text-sm font-bold tabular-nums ${textColor}`}>
202	            {formatPercent(pct)} utilizado
203	            {pct >= 100 && ' — Teto ultrapassado!'}
204	            {pct >= 90 && pct < 100 && ' — Atencao: proximo do limite!'}
205	          </p>
206	          <p className="text-xs text-gray-500 flex items-center gap-1">
207	            <Info size={12} />
208	            Alertas in-app ao atingir 80%, 90% e 100%. WhatsApp em breve.
209	          </p>
210	        </div>
211	      ) : (
212	        <div className="bg-gray-50 border-2 border-dashed border-gray-300 rounded-xl p-4 text-center">
213	          <p className="text-sm text-gray-500 font-bold">Nenhum teto configurado.</p>
214	          <p className="text-xs text-gray-400 mt-1">Configure para receber alertas antes de estourar o orcamento.</p>
215	        </div>
216	      )}
217	    </div>
218	  );
219	}
220	
221	// ---------------------------------------------------------------------------
222	// Subcomponente: RevenueCard
223	// ---------------------------------------------------------------------------
224	
225	interface RevenueCardProps {
226	  monthlyRevenueAmount: number | null;
227	  loading: boolean;
228	  onSave: (amount: number) => Promise<boolean>;
229	}
230	
231	function RevenueCard({ monthlyRevenueAmount, loading, onSave }: RevenueCardProps) {
232	  const [editing, setEditing] = useState(false);
233	  const [inputValue, setInputValue] = useState('');
234	  const [saving, setSaving] = useState(false);
235	  const { addToast } = useToast();
236	
237	  async function handleSave() {
238	    const parsed = parseFloat(inputValue.replace(',', '.'));
239	    if (isNaN(parsed) || parsed < 0) {
240	      addToast('Informe um valor valido (use 0 se nao houve faturamento).', 'error');
241	      return;
242	    }
243	    setSaving(true);
244	    const ok = await onSave(parsed);
245	    setSaving(false);
246	    if (ok) {
247	      addToast('Faturamento salvo!', 'success');
248	      setEditing(false);
249	      setInputValue('');
250	    } else {
251	      addToast('Erro ao salvar o faturamento. Tente novamente.', 'error');
252	    }
253	  }
254	
255	  if (loading) {
256	    return (
257	      <div className="bg-white border-2 border-black rounded-2xl p-6 animate-pulse space-y-4">
258	        <div className="h-6 bg-gray-200 rounded-xl w-1/2" />
259	        <div className="h-4 bg-gray-200 rounded-xl w-full" />
260	      </div>
261	    );
262	  }
263	
264	  return (
265	    <div className="bg-white border-2 border-black rounded-2xl p-6 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
266	      <div className="flex items-center justify-between mb-4">
267	        <div className="flex items-center gap-2">
268	          <TrendingDown size={20} strokeWidth={3} />
269	          <h2 className="text-xl font-black uppercase">Faturamento do Mes</h2>
270	        </div>
271	        <button
272	          onClick={() => {
273	            setEditing((e) => !e);
274	            setInputValue(monthlyRevenueAmount != null ? String(monthlyRevenueAmount) : '');
275	          }}
276	          className="text-sm font-black uppercase px-4 py-2 rounded-xl border-2 border-black hover:bg-black hover:text-white transition-colors"
277	          aria-label={editing ? 'Cancelar edicao do faturamento' : 'Informar faturamento do mes'}
278	        >
279	          {editing ? 'Cancelar' : monthlyRevenueAmount != null ? 'Atualizar' : 'Informar'}
280	        </button>
281	      </div>
282	
283	      {editing ? (
284	        <div className="space-y-3">
285	          <label htmlFor="revenueInput" className="block text-sm font-black uppercase text-gray-600">
286	            Faturamento bruto do mes (R$)
287	          </label>
288	          <input
289	            id="revenueInput"
290	            type="number"
291	            min="0"
292	            step="0.01"
293	            value={inputValue}
294	            onChange={(e) => setInputValue(e.target.value)}
295	            placeholder="Ex: 50000,00"
296	            className="w-full border-2 border-black rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-primary text-lg font-bold tabular-nums"
297	          />
298	          <p className="text-xs text-gray-500 flex items-center gap-1">
299	            <Info size={12} />
300	            Usado para calcular custo de freelas como % do faturamento. Nao compartilhado externamente.
301	          </p>
302	          <button
303	            onClick={handleSave}
304	            disabled={saving || inputValue === ''}
305	            className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
306	          >
307	            {saving ? 'Salvando...' : 'Salvar Faturamento'}
308	          </button>
309	        </div>
310	      ) : monthlyRevenueAmount != null ? (
311	        <div>
312	          <p className="text-xs font-bold uppercase text-gray-500">Faturamento declarado</p>
313	          <p className="text-3xl font-black tabular-nums text-blue-600">{formatBRL(monthlyRevenueAmount)}</p>
314	          <p className="text-xs text-gray-500 mt-1">Destrava o indicador custo-%-faturamento no painel abaixo.</p>
315	        </div>
316	      ) : (
317	        <div className="bg-blue-50 border-2 border-blue-200 rounded-xl p-4">
318	          <p className="text-sm font-bold text-blue-700">Informe o faturamento para desbloquear o indicador de custo-%-faturamento.</p>
319	          <p className="text-xs text-blue-500 mt-1">Dado privado, usado apenas para calcular a proporcao do custo com freelas.</p>
320	        </div>
321	      )}
322	    </div>
323	  );
324	}
325	
326	// ---------------------------------------------------------------------------
327	// Subcomponente: SkeletonBI
328	// ---------------------------------------------------------------------------
329	
330	function SkeletonBI() {
331	  return (
332	    <div className="space-y-6 animate-pulse">
333	      {[...Array(4)].map((_, i) => (
334	        <div key={i} className="bg-white border-2 border-black rounded-2xl p-6 space-y-4">
335	          <div className="h-6 bg-gray-200 rounded-xl w-1/3" />
336	          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
337	            <div className="h-16 bg-gray-200 rounded-xl" />
338	            <div className="h-16 bg-gray-200 rounded-xl" />
339	          </div>
340	          <div className="space-y-3">
341	            {[...Array(3)].map((_, j) => (
342	              <div key={j} className="h-14 bg-gray-200 rounded-xl" />
343	            ))}
344	          </div>
345	        </div>
346	      ))}
347	    </div>
348	  );
349	}
