351	// ---------------------------------------------------------------------------
352	// Pagina principal
353	// ---------------------------------------------------------------------------
354	
355	type PeriodKey = 'current' | 'previous';
356	
357	export default function CompanyFinancial() {
358	  const [periodKey, setPeriodKey] = useState<PeriodKey>('current');
359	  const [showSpendWorkerAll, setShowSpendWorkerAll] = useState(false);
360	
361	  const period: BIPeriod = periodKey === 'current' ? currentMonthPeriod() : previousMonthPeriod();
362	
363	  const {
364	    spendLimit,
365	    monthlyRevenue,
366	    loading: limitLoading,
367	    upsertSpendLimit,
368	    upsertMonthlyRevenue,
369	  } = useSpendLimit();
370	
371	  const {
372	    data,
373	    loading: biLoading,
374	    error: biError,
375	    refresh: refreshBI,
376	  } = useFinancialBI(period);
377	
378	  const accumulatedSpend = data?.accumulatedSpend.totalAmount ?? 0;
379	  const spendByWorker = data?.spendByWorker ?? [];
380	  const costRatio = data?.costRatio;
381	  const noShowCost = data?.noShowCost;
382	  const concentrationFlags = data?.concentrationFlags ?? [];
383	
384	  const WORKER_PREVIEW = 5;
385	  const workersToShow = showSpendWorkerAll ? spendByWorker : spendByWorker.slice(0, WORKER_PREVIEW);
386	  const flaggedWorkers = concentrationFlags.filter((f) => f.flagged);
387	
388	  async function handleSaveLimit(amount: number, thresholds: number[]): Promise<boolean> {
389	    const ok = await upsertSpendLimit({ amount, alertThresholds: thresholds });
390	    if (ok) refreshBI();
391	    return ok;
392	  }
393	
394	  async function handleSaveRevenue(amount: number): Promise<boolean> {
395	    const ok = await upsertMonthlyRevenue(amount);
396	    if (ok) refreshBI();
397	    return ok;
398	  }
399	
400	  return (
401	    <div className="flex flex-col gap-8 pb-20 md:pb-12 font-sans text-accent max-w-4xl mx-auto">
402	
403	      {/* Header */}
404	      <header>
405	        <h1 className="text-4xl font-black uppercase tracking-tighter mb-2">Financeiro</h1>
406	        <p className="text-gray-500 text-sm">Controle de gasto, faturamento e indicadores de freelas.</p>
407	      </header>
408	
409	      {/* Seletor de periodo */}
410	      <div className="flex gap-3">
411	        {(['current', 'previous'] as PeriodKey[]).map((key) => {
412	          const p = key === 'current' ? currentMonthPeriod() : previousMonthPeriod();
413	          const isActive = periodKey === key;
414	          return (
415	            <button
416	              key={key}
417	              onClick={() => setPeriodKey(key)}
418	              className={`px-5 py-2.5 rounded-xl border-2 font-black uppercase text-sm transition-all
419	                ${isActive
420	                  ? 'bg-black text-white border-black shadow-[4px_4px_0px_0px_rgba(0,166,81,1)]'
421	                  : 'bg-white text-gray-500 border-black hover:bg-gray-100'
422	                }`}
423	            >
424	              {periodLabel(p)}
425	            </button>
426	          );
427	        })}
428	      </div>
429	
430	      {/* Teto + Faturamento */}
431	      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
432	        <SpendLimitCard
433	          spendLimitAmount={spendLimit?.amount ?? null}
434	          accumulatedSpend={accumulatedSpend}
435	          loading={limitLoading}
436	          onSave={handleSaveLimit}
437	        />
438	        <RevenueCard
439	          monthlyRevenueAmount={monthlyRevenue?.amount ?? null}
440	          loading={limitLoading}
441	          onSave={handleSaveRevenue}
442	        />
443	      </div>
444	
445	      {/* BI Section */}
446	      {biLoading ? (
447	        <SkeletonBI />
448	      ) : biError ? (
449	        <div className="bg-red-50 border-2 border-red-200 rounded-2xl p-6 text-center">
450	          <p className="font-black text-red-600 uppercase text-sm">{biError}</p>
451	          <button
452	            onClick={refreshBI}
453	            className="mt-3 px-6 py-2 rounded-xl border-2 border-black font-black uppercase text-sm hover:bg-black hover:text-white transition-colors"
454	          >
455	            Tentar novamente
456	          </button>
457	        </div>
458	      ) : !data || (accumulatedSpend === 0 && spendByWorker.length === 0) ? (
459	        <div className="bg-white border-2 border-black rounded-2xl p-10 text-center shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
460	          <BarChart2 size={40} className="mx-auto mb-4 text-gray-300" />
461	          <p className="font-black text-gray-500 uppercase text-sm">Nenhum dado no periodo selecionado.</p>
462	          <p className="text-xs text-gray-400 mt-1">Os indicadores aparecem conforme os turnos sao concluidos.</p>
463	        </div>
464	      ) : (
465	        <div className="space-y-6">
466	
467	          {/* BI-3: Ratio custo/hora + custo-%-faturamento */}
468	          {costRatio && (
469	            <section className="bg-white border-2 border-black rounded-2xl p-6 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
470	              <div className="flex items-center gap-2 mb-5">
471	                <BarChart2 size={20} strokeWidth={3} />
472	                <h2 className="text-xl font-black uppercase">Indicadores de Custo</h2>
473	              </div>
474	
475	              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
476	                {/* Custo total */}
477	                <div className="bg-gray-50 border-2 border-black rounded-xl p-4">
478	                  <p className="text-xs font-black uppercase text-gray-500 mb-1">Custo Total</p>
479	                  <p className="text-2xl font-black tabular-nums">{formatBRL(costRatio.totalCost)}</p>
480	                  <p className="text-xs text-gray-400 mt-1">{costRatio.totalHours > 0 ? `${formatHours(costRatio.totalHours)} de trabalho` : 'Sem horas registradas'}</p>
481	                </div>
482	
483	                {/* Custo por hora */}
484	                <div className="bg-gray-50 border-2 border-black rounded-xl p-4">
485	                  <p className="text-xs font-black uppercase text-gray-500 mb-1">Custo / Hora</p>
486	                  {costRatio.costPerHour != null ? (
487	                    <p className="text-2xl font-black tabular-nums">{formatBRL(costRatio.costPerHour)}<span className="text-sm font-bold">/h</span></p>
488	                  ) : (
489	                    <p className="text-sm text-gray-400 font-bold">—</p>
490	                  )}
491	                  <p className="text-xs text-gray-400 mt-1">Media no periodo</p>
492	                </div>
493	
494	                {/* Custo % faturamento */}
495	                <div className={`border-2 rounded-xl p-4 ${costRatio.costPercentRevenue != null ? 'bg-blue-50 border-blue-200' : 'bg-gray-50 border-dashed border-gray-300'}`}>
496	                  <p className="text-xs font-black uppercase text-gray-500 mb-1">Custo % Faturamento</p>
497	                  {costRatio.costPercentRevenue != null ? (
498	                    <>
499	                      <p className="text-2xl font-black tabular-nums text-blue-600">{formatPercent(costRatio.costPercentRevenue)}</p>
500	                      <p className="text-xs text-gray-400 mt-1">do faturamento declarado</p>
501	                    </>
502	                  ) : (
503	                    <div>
504	                      <p className="text-sm text-gray-400 font-bold">Bloqueado</p>
505	                      <p className="text-xs text-blue-600 mt-1 font-bold">Informe o faturamento acima para desbloquear.</p>
506	                    </div>
507	                  )}
508	                </div>
509	              </div>
510	            </section>
511	          )}
512	
513	          {/* BI-2: Gasto por freela */}
514	          {spendByWorker.length > 0 && (
515	            <section className="bg-white border-2 border-black rounded-2xl p-6 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
516	              <div className="flex items-center justify-between mb-5">
517	                <div className="flex items-center gap-2">
518	                  <Users size={20} strokeWidth={3} />
519	                  <h2 className="text-xl font-black uppercase">Gasto por Freela</h2>
520	                </div>
521	                <span className="text-xs font-bold bg-gray-100 text-gray-600 px-2 py-1 rounded-full border border-black">
522	                  {spendByWorker.length} freela{spendByWorker.length !== 1 ? 's' : ''}
523	                </span>
524	              </div>
525	
526	              <div className="space-y-3">
527	                {workersToShow.map((w, idx) => (
